DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT101-S3-Q2$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It treats something that is necessary for bringing about a state of affairs as something that is sufficient to bring about that state of affairs.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT101-S3-Q2 A'; END IF; END $guard$;
