DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It presumes without giving justification that survival of the company has been a good thing.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT102-S2-Q18 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$It does not take into account that there are alternatives to declaring bankruptcy.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT102-S2-Q18 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$It presumes without giving justification that only decreased demand can ever be the cause of decreased profits.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT102-S2-Q18 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$It does not allow for the possibility that profits will decrease only slightly during the next fiscal year.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT102-S2-Q18 D'; END IF; END $guard$;
