DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT102-S2-Q18'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion (consequently)$batch01$, $batch01$The company's only options are to reduce planned expansion or eliminate some less profitable current operations.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Demand and profit have fallen. Continued decline may cause bankruptcy, so preventing further profit decline matters.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Granted, the company needs to stop profits falling. Why must it choose one of those two cost cuts? It might increase revenue through a new product, revise prices, or find a third cost saving. The urgency of the goal does not prove an exhaustive list of ways to reach it. We need only one possible third way to challenge “only.”$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the missing alternatives to stopping profit decline, not merely alternatives to bankruptcy.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$Whether the company's survival is good does not show that the two listed measures exhaust its ways to prevent further loss.$batch01$), ($batch01$B$batch01$, $batch01$This sounds tempting because bankruptcy is mentioned. But the president's *only options* claim concerns stopping the decrease in profits. A way to survive after profits keep falling would not be a third way to stop that fall.$batch01$), ($batch01$C$batch01$, $batch01$The president says decreased demand explains this year's low profits, not that decreased demand is the *only possible cause* of decreased profits. Even if another factor could lower profits, that would not identify the flaw in the supposedly exhaustive list of two measures for preventing a further decline.$batch01$), ($batch01$D$batch01$, $batch01$Even a slight further decrease is a decrease. Its size does not show that there is another option for preventing it.$batch01$), ($batch01$E$batch01$, $batch01$“Other ways to stop the decrease” is exactly the omitted third route. If another route exists, reducing expansion and eliminating operations are not the *only* options. This is the False Choice flaw.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT102-S2-Q18$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;

