INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$The proposed legislation must be defeated.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Some supporters belong to groups that used violence in the past; other supporters face tax-evasion indictment.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Suppose every allegation about these supporters is true. What does that tell us about whether more paid vacation, higher overtime wages, or paid child care is a good law? Nothing by itself. A disreputable person can support a good proposal. The columnist offers no argument about the proposal's effects.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Look for the move from the character of the law's *supporters* to a verdict against the law.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT102-S4-Q4$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$“Originators” means the people who proposed or created the legislation. The stimulus identifies people supporting it. We are not told who originated it.$batch01$), ($batch01$B$batch01$, $batch01$The columnist assails the law because some *supporters* have questionable histories or face charges. That attacks the source of support rather than the legislation's merits. A charge is not even a conviction, but the flaw remains even if the character allegations are granted.$batch01$), ($batch01$C$batch01$, $batch01$The columnist names no people who would be adversely affected and makes no plea on their behalf. The appeal is against allegedly bad supporters.$batch01$), ($batch01$D$batch01$, $batch01$The argument says nothing about the number of supporters inside or outside the legislature. It targets their character, not their count.$batch01$), ($batch01$E$batch01$, $batch01$The columnist never claims the supporters depend on manufacturers' success or act inconsistently. That would be a different attack on them.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT102-S4-Q4$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;

