INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$At least 80 percent of people lack enough medical knowledge for sound personal medical choices or public health policy decisions.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Only 20 percent know enough about DNA to understand a DNA news story. The 90 percent self-assessment is background contrast.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The arithmetic gives 80 percent who cannot understand that story. Why must understanding DNA be required for every well-informed medical or policy decision? One could make an informed choice about a broken bone without understanding DNA. The argument treats a particular subject as a necessary condition for broad health-care judgment.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Look for the unproved requirement: DNA knowledge is essential to the decisions in the conclusion.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT104-S1-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$This asks whether DNA understanding is *enough* for good choices. The argument needs to show that DNA understanding is *required* for good choices. Even if some DNA experts make poor choices, the inference about people without DNA knowledge remains the target.$batch01$), ($batch01$B$batch01$, $batch01$The conclusion describes what individuals know. It does not establish a particular quota of informed people needed for policy to be good.$batch01$), ($batch01$C$batch01$, $batch01$The argument does not infer policy skill from personal medical skill. It draws both conclusions from lack of DNA knowledge.$batch01$), ($batch01$D$batch01$, $batch01$To infer that the 80 percent who cannot understand a DNA story also cannot make informed personal or policy decisions, DNA understanding would have to be essential to those decisions. The evidence never establishes that requirement.$batch01$), ($batch01$E$batch01$, $batch01$The 90 percent self-report might imply that many overestimate their knowledge *if* the DNA criterion were valid. But the objection concerns whether the criterion itself is required for informed choices.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT104-S1-Q2$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;

