INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The argument is about Marion's particular schedule, not a problem mistakenly treated as hers alone.$batch01$), ($batch01$B$batch01$, $batch01$Marion knows the bridge is closed. The flaw is not that she overlooks a consequence of a known fact; the author overlooks her ability to choose the train despite disliking it.$batch01$), ($batch01$C$batch01$, $batch01$This choice tempts because Marion's preferences matter to the story. But it proposes that *people generally* want to avoid being late, while the argument's evidence is specific: Marion hates taking the train. Even if she wants very badly to be on time, she still has the train option. The flaw is converting dislike of that option into its impossibility, not projecting a general human preference onto Marion.$batch01$), ($batch01$D$batch01$, $batch01$Her hatred of trains is evidence she may choose not to take one. It does not exclude that alternative. A disfavored option is still an option, and taking it could defeat the conclusion that she cannot avoid being late.$batch01$), ($batch01$E$batch01$, $batch01$The train is a possible route whether or not Marion has a “good reason” to take it. The issue is availability, not whether an occasional choice lacks a good reason.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT105-S1-Q26$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;

