DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT114-S1-Q6$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$The argument presumes, without providing warrant, that one always wants expert guidance in making decisions about one’s health.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT114-S1-Q6 B'; END IF; END $guard$;
