INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$The opponent's argument for changing zoning laws should not be taken seriously.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Although the opponent advocates encouraging housing such as apartment buildings, he himself lives in a house in the country.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Living in a country house does not settle whether current zoning rules overpromote suburban single-family homes. The opponent could even prefer his own home while correctly arguing that the city should make room for other residents' choices. The politician needs to answer the housing-policy claim, not the opponent's lifestyle.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Identify the ad hominem move: using a person's conduct to dismiss the merits of that person's argument.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT114-S4-Q8$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The politician may be prejudiced against apartments, but describing the opponent's residence does not establish that motive. The flaw we can verify is reliance on an irrelevant personal fact.$batch01$), ($batch01$B$batch01$, $batch01$Where apartment buildings can be built does not address whether the opponent's home undermines his argument. His proposal can be assessed without this suburban-versus-center comparison.$batch01$), ($batch01$C$batch01$, $batch01$Knowing the politician's own living arrangement would not make the opponent's argument more or less sound.$batch01$), ($batch01$D$batch01$, $batch01$Whether the opponent lives in a country house has no bearing on whether zoning laws should encourage more varied housing. The criticism attacks the advocate's lifestyle while leaving the policy reasoning unanswered.$batch01$), ($batch01$E$batch01$, $batch01$The opponent need never have lived in an apartment for his present claim about zoning to be sound. A past apartment residence would not be the missing defense of his argument.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT114-S4-Q8$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;

