INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Legislators should vote against the environmental bill.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$It is popular but would have mainly negative economic consequences, especially for attracting new businesses. Great leaders look beyond popularity to sound policy.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The bill's economic costs matter, and popularity by itself would not justify it. But a vote requires weighing *all* important consequences. Environmental or health benefits might outweigh those costs. The speaker gives a reason against the bill and treats it as decisive without examining potential reasons for it.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the omitted noneconomic benefits that could outweigh the acknowledged economic downside.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT115-S2-Q14$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
