DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch01$530b861d-8d2a-4e8d-8a83-b394c89148d4$batch01$ AND (s.id::text,s.position,s.label,s.body) IN (VALUES ($batch01$1fef53e3-e7e6-4e67-a73a-586afc6fab73$batch01$, 0, $batch01$Conclusion$batch01$, $batch01$The ancient Egyptians were the first society to produce alcoholic beverages.$batch01$), ($batch01$e29f83ec-ca14-4f4a-92d1-f1a4fdfcbbc6$batch01$, 1, $batch01$Evidence$batch01$, $batch01$An Egyptian cup dating from 2000 B.C. depicts a brewery and contains residue of alcoholic beer — older than the Babylonian fermentation evidence from 1500 B.C.$batch01$), ($batch01$df1b22a1-32f7-4e82-bcfd-fd61bec76946$batch01$, 2, $batch01$Evaluate$batch01$, $batch01$"First known" and "first ever" are different. The Egyptian cup is the earliest *archaeological evidence* of alcoholic beverage production we have found, but other societies — including the Egyptians themselves earlier or some entirely different civilization — could have produced alcohol earlier without leaving evidence behind, or with evidence we have not yet found.$batch01$), ($batch01$0ada7665-3af7-4a79-8e8c-2da7c382c1f4$batch01$, 3, $batch01$Goal$batch01$, $batch01$Find an answer that points out the gap between "earliest evidence we have" and "first ever."$batch01$))) <> 4 THEN RAISE EXCEPTION 'Existing step changed: PT119-S2-Q24'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The author is not using one Egyptian cup to generalize about what most Egyptians did. The cup establishes an instance of alcoholic beer in Egypt by 2000 B.C.; the issue is whether that instance was the world's first.$batch01$), ($batch01$B$batch01$, $batch01$"Alcoholic beverage" includes wine and beer in both the evidence and the conclusion. The argument compares dates, not two meanings of the term.$batch01$), ($batch01$C$batch01$, $batch01$The author does not say Babylonian wine production depended on Egyptian beer production. Being earlier than one known Babylonian example is offered as evidence for priority, not for transmission of technology.$batch01$), ($batch01$D$batch01$, $batch01$The cup is older than the cited Babylonian evidence, so Egypt has the earlier *known* example of the two. Another society might have made alcohol even earlier without leaving evidence we have found. The oldest discovered instance need not be the first historical instance.$batch01$), ($batch01$E$batch01$, $batch01$The author supplies the 1500 B.C. Babylonian wine date as background. Even if that date were well documented, the Egyptian cup would not establish that no society produced alcohol before Egypt.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT119-S2-Q24$batch01$ AND e.id=$batch01$530b861d-8d2a-4e8d-8a83-b394c89148d4$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;

